const node=document.getElementById('comments');
if(node){
  const slug=node.dataset.story,lang=node.dataset.lang;
  const words={pt:{heading:'Comentários',name:'Nome público',body:'Comentário',submit:'Enviar comentário',pending:'Enviado para aprovação. Ele aparecerá após a moderação.',empty:'Ainda não há comentários aprovados.',error:'Não foi possível carregar os comentários.',check:'Escreva seu nome e comentário.'},en:{heading:'Comments',name:'Public name',body:'Comment',submit:'Send comment',pending:'Submitted for review. It will appear after moderation.',empty:'No approved comments yet.',error:'Could not load comments.',check:'Enter your name and comment.'},es:{heading:'Comentarios',name:'Nombre público',body:'Comentario',submit:'Enviar comentario',pending:'Enviado para aprobación. Aparecerá después de la moderación.',empty:'Todavía no hay comentarios aprobados.',error:'No se pudieron cargar los comentarios.',check:'Escribe tu nombre y comentario.'}}[lang];
  const heading=document.createElement('h2');heading.textContent=words.heading;
  const list=document.createElement('div');list.className='comment-list';
  const status=document.createElement('p');status.className='comment-status';status.setAttribute('role','status');
  const form=document.createElement('form');form.className='comment-form';
  const nameLabel=document.createElement('label');nameLabel.textContent=words.name;const name=document.createElement('input');name.required=true;name.maxLength=50;name.minLength=2;nameLabel.append(name);
  const bodyLabel=document.createElement('label');bodyLabel.textContent=words.body;const body=document.createElement('textarea');body.required=true;body.maxLength=2000;body.minLength=3;bodyLabel.append(body);
  const honey=document.createElement('input');honey.name='website';honey.className='comment-honey';honey.tabIndex=-1;honey.setAttribute('aria-hidden','true');honey.autocomplete='off';
  const button=document.createElement('button');button.type='submit';button.className='primary';button.textContent=words.submit;
  form.append(nameLabel,bodyLabel,honey,button);node.append(heading,list,status,form);
  fetch(`/api/comments?story=${encodeURIComponent(slug)}`).then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{list.replaceChildren();if(!data.comments.length){list.textContent=words.empty;return}for(const item of data.comments){const section=document.createElement('article');section.className='comment';const author=document.createElement('strong');author.textContent=item.author;const date=document.createElement('small');date.textContent=new Date(item.created_at).toLocaleDateString(lang);const content=document.createElement('p');content.textContent=item.body;section.append(author,date,content);list.append(section)}}).catch(()=>{list.textContent=words.error});
  form.addEventListener('submit',async event=>{event.preventDefault();if(!name.value.trim()||!body.value.trim()){status.textContent=words.check;return}button.disabled=true;try{const response=await fetch('/api/comments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({story:slug,lang,author:name.value,body:body.value,website:honey.value})});const data=await response.json();if(!response.ok)throw Error(data.error||words.error);status.textContent=words.pending;form.reset()}catch(error){status.textContent=error.message}finally{button.disabled=false}});
}
